insert into public.collections (id, slug, status, tone, sort_order, name, description, story_title, story) values ('33333333-3333-4333-8333-0000000000a1', 'bo-suu-tap-dau-tien', 'published', 'amber', 1, '{"vi":"Bộ sưu tập đầu tiên","en":"The First Collection","zh":"首个系列"}'::jsonb, '{"vi":"Năm bức tranh, năm chiếc đèn giấy dó, năm câu chuyện đầu tiên của LAMVI.","en":"Five paintings, five dó paper lanterns, the first five stories of LAMVI.","zh":"五幅画、五盏纸灯、LAMVI 的第一批五个故事。"}'::jsonb, '{"vi":"Từ một tờ giấy đến ánh sáng","en":"From a sheet of paper to light","zh":"从一张纸到一束光"}'::jsonb, '{"vi":"Một tờ giấy đi qua bao nhiêu đôi tay trước khi thành ánh sáng? Giấy dó thủ công ở Dương Ổ – Phong Khê, lớp điệp và phần nghệ thuật Đông Hồ, rồi những chiếc đèn được hoàn thiện ở LAMVI. Đủ năm chiếc đèn là đủ năm câu chuyện: mùa gặt xứng đáng, bốn linh vật, phúc và lộc song toàn, tiếng gà gọi bình minh và đàn lợn quây quần.","en":"How many hands does a sheet of paper pass through before it becomes light? Handmade dó paper from Duong O – Phong Khe, the điệp coating and the Dong Ho artwork, then lanterns finished at LAMVI. Five lanterns make five stories: a well-earned harvest, four sacred creatures, blessings and fortune together, roosters calling the dawn, and a gathered herd of pigs.","zh":"一张纸在变成光之前要经过多少双手？杨坞—风溪的手工纸、贝壳粉涂层与东湖版画，再由 LAMVI 完成灯的制作。集齐五盏灯，便是五个故事：当之无愧的丰收、四灵、福禄双全、雄鸡报晓与成群的猪。"}'::jsonb) on conflict (id) do nothing;
insert into public.products (id, slug, kind, status, price, tone, sort_order, name, description, badge, collection_slug, piece_order, specs, story) values ('11111111-1111-4111-8111-0000000000a1', 'den-thu-hoach', 'single', 'published', 1400000, 'amber', 1, '{"vi":"Đèn Thu Hoạch","en":"Harvest Lantern (Thu Hoach)","zh":"丰收灯（Thu Hoạch）"}'::jsonb, '{"vi":"Gặt mùa xứng đáng — dành cho những hành trình được vun trồng bằng sự bền bỉ","en":"A well-earned harvest — for journeys cultivated with perseverance","zh":"收获当之无愧的季节——献给用坚持耕耘的旅程"}'::jsonb, null, 'bo-suu-tap-dau-tien', 1, '{"size":{"vi":"Thân đèn cao 20 cm, đường kính 12 cm; đế gỗ cao 5 cm, đường kính 12 cm","en":"Lantern body 20 cm tall, 12 cm in diameter; wooden base 5 cm tall, 12 cm in diameter","zh":"灯身高 20 厘米、直径 12 厘米；木底座高 5 厘米、直径 12 厘米"},"material":{"vi":"Giấy dó Dương Ổ – Phong Khê phủ điệp, artwork tranh dân gian Đông Hồ; đế gỗ","en":"Dó paper from Duong O – Phong Khe, coated with điệp, artwork from Dong Ho folk painting; wooden base","zh":"杨坞—风溪手工纸，涂贝壳粉（điệp），图案取自东湖民间版画；木底座"},"light":{"vi":"Đèn LED ánh sáng vàng ấm, dùng điện cắm trực tiếp","en":"Warm-white LED, plugs directly into mains power","zh":"暖黄色 LED，直接插电使用"},"leadTime":{"vi":"Trung bình 5–7 ngày làm việc","en":"On average 5–7 working days","zh":"平均 5–7 个工作日"}}'::jsonb, '{"vi":"Có những mùa quả ngọt không bắt đầu từ ngày thu hoạch. Nó bắt đầu từ những buổi sáng ra đồng thật sớm, những ngày nắng gắt, những hôm mưa dài và cả những khoảng thời gian chỉ biết kiên nhẫn chờ cây lớn lên.\n\nNgười ta thường chỉ nhìn thấy khoảnh khắc thành quả được mang về. Nhưng phía sau khoảnh khắc ấy là rất nhiều ngày không ai nhìn thấy: là công sức, là sự bền bỉ và là niềm tin rằng những gì mình vun trồng rồi sẽ có ngày kết trái.\n\nKhi hình ảnh ấy được đưa lên giấy dó và đặt dưới ánh sáng vàng ấm, LAMVI muốn giữ lại cảm giác rất quen thuộc của đời sống Việt: một mùa làm lụng, một mùa chờ đợi, rồi cuối cùng là khoảnh khắc được nhìn thấy thành quả từ chính đôi tay mình.\n\nĐèn Thu Hoạch không chỉ kể câu chuyện của người nông dân. Nó còn có thể là câu chuyện của bất kỳ ai đang đi qua một hành trình dài, âm thầm cố gắng và chờ đến ngày được nhìn thấy \"mùa quả ngọt\" của riêng mình.","en":"Some sweet harvests do not begin on harvest day. They begin on very early mornings in the field, on scorching days and long rainy ones, and in all the time spent simply waiting patiently for the plants to grow.\n\nPeople usually see only the moment the harvest is brought home. Behind it lie many days no one sees: effort, perseverance, and the belief that what you plant will one day bear fruit.\n\nWhen this image is set on dó paper and placed under a warm yellow light, LAMVI wants to keep a feeling that is deeply familiar in Vietnamese life: a season of work, a season of waiting, and finally the moment of seeing the result of your own hands.\n\nThe Harvest lantern does not only tell the story of the farmer. It can be the story of anyone on a long journey, quietly trying and waiting for the day they see their own \"sweet harvest\".","zh":"有些甜美的收成，并不是从收获那天开始的。它始于清晨早早下地，始于烈日与连绵的雨天，也始于只能耐心等待作物生长的那些日子。\n\n人们往往只看见成果被带回家的那一刻，却看不见背后许多无人知晓的日子：付出、坚持，以及相信自己种下的终会结果的信念。\n\n当这幅画落在 dó 纸上、置于暖黄的灯光下，LAMVI 想留住越南生活里那份熟悉的感觉：一季耕作，一季等待，最后是亲眼看见自己双手成果的时刻。\n\n丰收灯讲的不只是农人的故事。它也可以是任何一个正走在漫长旅途中、默默努力并等待属于自己“甜美收成”的人的故事。"}'::jsonb) on conflict (id) do nothing;
insert into public.products (id, slug, kind, status, price, tone, sort_order, name, description, badge, collection_slug, piece_order, specs, story) values ('11111111-1111-4111-8111-0000000000a2', 'den-tu-linh', 'single', 'published', 1400000, 'dusk', 2, '{"vi":"Đèn Tứ Linh","en":"Four Sacred Creatures Lantern (Tu Linh)","zh":"四灵灯（Tứ Linh）"}'::jsonb, '{"vi":"Long, Lân, Quy, Phụng — bốn linh vật với nhiều chi tiết để khám phá khi lại gần","en":"Dragon, Qilin, Turtle and Phoenix — four creatures with details to discover up close","zh":"龙、麟、龟、凤——四灵，近看有许多细节等你发现"}'::jsonb, null, 'bo-suu-tap-dau-tien', 2, '{"size":{"vi":"Thân đèn cao 20 cm, đường kính 12 cm; đế gỗ cao 5 cm, đường kính 12 cm","en":"Lantern body 20 cm tall, 12 cm in diameter; wooden base 5 cm tall, 12 cm in diameter","zh":"灯身高 20 厘米、直径 12 厘米；木底座高 5 厘米、直径 12 厘米"},"material":{"vi":"Giấy dó Dương Ổ – Phong Khê phủ điệp, artwork tranh dân gian Đông Hồ; đế gỗ","en":"Dó paper from Duong O – Phong Khe, coated with điệp, artwork from Dong Ho folk painting; wooden base","zh":"杨坞—风溪手工纸，涂贝壳粉（điệp），图案取自东湖民间版画；木底座"},"light":{"vi":"Đèn LED ánh sáng vàng ấm, dùng điện cắm trực tiếp","en":"Warm-white LED, plugs directly into mains power","zh":"暖黄色 LED，直接插电使用"},"leadTime":{"vi":"Trung bình 5–7 ngày làm việc","en":"On average 5–7 working days","zh":"平均 5–7 个工作日"}}'::jsonb, '{"vi":"Tứ Linh là mẫu LAMVI muốn người xem không chỉ nhìn một lần rồi lướt qua. Ở khoảng cách xa, bạn thấy tổng thể của chiếc đèn. Khi lại gần, từng phần Long – Lân – Quy – Phụng lần lượt hiện ra trên bề mặt giấy.\n\nBốn linh vật cùng xuất hiện trên một thân đèn, như bốn lời chúc đi cùng nhau. Mỗi chi tiết nhỏ trên tranh đều đáng để dừng lại, xoay chiếc đèn và nhìn từ nhiều phía.\n\nVà khi bật sáng, bố cục ấy lại có thêm một trạng thái khác: ánh vàng ấm đi qua lớp giấy dó phủ điệp, làm các mảng sáng – tối trở nên rõ hơn và cảm giác của màu cũng khác đi.\n\nHãy thử tìm xem: bạn ấn tượng với phần nào nhất — Long, Lân, Quy hay Phụng?","en":"Tứ Linh is a lantern LAMVI wants people to look at more than once. From a distance you see the whole piece. Come closer and the Dragon, Qilin, Turtle and Phoenix appear one by one on the paper.\n\nFour sacred creatures share one lantern body, like four wishes travelling together. Every small detail is worth pausing for: turn the lantern and look from different sides.\n\nSwitch it on and the composition takes on another state: warm light passes through the điệp-coated dó paper, the lights and darks become clearer, and the colours feel different.\n\nTry finding out which part stays with you most: the Dragon, Qilin, Turtle or Phoenix?","zh":"四灵这一款，LAMVI 希望人们不只看一眼就走开。远看，是整盏灯的全貌；走近，龙、麟、龟、凤便一一在纸面上浮现。\n\n四种灵物同在一个灯身上，像四个同行的祝福。每一处小细节都值得停下来细看：转动灯身，从不同角度欣赏。\n\n点亮之后，画面又有另一种状态：暖黄的光透过涂了贝壳粉的 dó 纸，明暗更加分明，色彩的感觉也随之不同。\n\n不妨找一找：龙、麟、龟、凤，哪一部分最让你印象深刻？"}'::jsonb) on conflict (id) do nothing;
insert into public.products (id, slug, kind, status, price, tone, sort_order, name, description, badge, collection_slug, piece_order, specs, story) values ('11111111-1111-4111-8111-0000000000a3', 'den-phuc-loc-song-toan', 'single', 'published', 1400000, 'dawn', 3, '{"vi":"Đèn Phúc Lộc Song Toàn","en":"Blessings and Fortune Lantern (Phuc Loc Song Toan)","zh":"福禄双全灯（Phúc Lộc Song Toàn）"}'::jsonb, '{"vi":"Một món quà, hai lời chúc Phúc và Lộc","en":"One gift, two wishes: Blessings and Fortune","zh":"一份礼物，两重祝福：福与禄"}'::jsonb, null, 'bo-suu-tap-dau-tien', 3, '{"size":{"vi":"Thân đèn cao 20 cm, đường kính 12 cm; đế gỗ cao 5 cm, đường kính 12 cm","en":"Lantern body 20 cm tall, 12 cm in diameter; wooden base 5 cm tall, 12 cm in diameter","zh":"灯身高 20 厘米、直径 12 厘米；木底座高 5 厘米、直径 12 厘米"},"material":{"vi":"Giấy dó Dương Ổ – Phong Khê phủ điệp, artwork tranh dân gian Đông Hồ; đế gỗ","en":"Dó paper from Duong O – Phong Khe, coated with điệp, artwork from Dong Ho folk painting; wooden base","zh":"杨坞—风溪手工纸，涂贝壳粉（điệp），图案取自东湖民间版画；木底座"},"light":{"vi":"Đèn LED ánh sáng vàng ấm, dùng điện cắm trực tiếp","en":"Warm-white LED, plugs directly into mains power","zh":"暖黄色 LED，直接插电使用"},"leadTime":{"vi":"Trung bình 5–7 ngày làm việc","en":"On average 5–7 working days","zh":"平均 5–7 个工作日"}}'::jsonb, '{"vi":"Nếu một món quà có thể gửi đi hai lời chúc… \"Phúc\" và \"Lộc\" ngay trong tên gọi đã khiến đây trở thành một trong những mẫu đèn dành cho việc trao tặng.\n\nChiếc đèn giữ cấu trúc tinh gọn: hình ảnh và ánh sáng nói lên phần của mình, còn lời nhắn riêng của người tặng được mở ra qua mã QR trên thiệp cảm ơn.\n\nNhìn chiếc đèn — thấy hình ảnh và ánh sáng. Quét QR — mở câu chuyện của mẫu và lời chúc dành riêng cho người nhận.\n\nTân gia, khai trương, cuối năm hay một cột mốc riêng của người nhận: mỗi dịp đều có thể có lý do để Phúc Lộc Song Toàn được trao đi.","en":"If one gift could carry two wishes… \"Phúc\" (blessings) and \"Lộc\" (fortune) are right there in the name, which makes this one of the lanterns made for giving.\n\nThe lantern keeps a lean structure: the image and the light speak for themselves, while the giver''s personal message opens through the QR code on the thank-you card.\n\nLook at the lantern — you see the image and the light. Scan the QR code — you open the story of this piece and the message written just for you.\n\nA housewarming, an opening, the end of the year or a milestone of your own: every occasion can be a reason to give Phúc Lộc Song Toàn.","zh":"如果一份礼物能带去两重祝福……“福”与“禄”就写在名字里，让这盏灯成为专为赠送而生的款式之一。\n\n灯身保持简洁：图案与光线自会说话，而送礼人的专属留言，则通过感谢卡上的二维码打开。\n\n看灯——看见图案与光；扫码——打开这款灯的故事，以及写给你的祝福。\n\n乔迁、开业、年终，或是收礼人自己的某个里程碑：每个场合，都可以成为赠出“福禄双全”的理由。"}'::jsonb) on conflict (id) do nothing;
insert into public.products (id, slug, kind, status, price, tone, sort_order, name, description, badge, collection_slug, piece_order, specs, story) values ('11111111-1111-4111-8111-0000000000a4', 'den-ga-tam-duong-khai-thai', 'single', 'published', 1400000, 'moss', 4, '{"vi":"Đèn Gà Tam Dương Khai Thái","en":"Rooster Lantern (Tam Duong Khai Thai)","zh":"三阳开泰雄鸡灯（Tam Dương Khai Thái）"}'::jsonb, '{"vi":"Hai chú gà trống cất tiếng gọi bình minh — lời chúc cho một khởi đầu thuận lợi","en":"Two roosters calling the dawn — a wish for an auspicious beginning","zh":"两只雄鸡啼晓——祝愿一个顺遂的开端"}'::jsonb, null, 'bo-suu-tap-dau-tien', 4, '{"size":{"vi":"Thân đèn cao 20 cm, đường kính 12 cm; đế gỗ cao 5 cm, đường kính 12 cm","en":"Lantern body 20 cm tall, 12 cm in diameter; wooden base 5 cm tall, 12 cm in diameter","zh":"灯身高 20 厘米、直径 12 厘米；木底座高 5 厘米、直径 12 厘米"},"material":{"vi":"Giấy dó Dương Ổ – Phong Khê phủ điệp, artwork tranh dân gian Đông Hồ; đế gỗ","en":"Dó paper from Duong O – Phong Khe, coated with điệp, artwork from Dong Ho folk painting; wooden base","zh":"杨坞—风溪手工纸，涂贝壳粉（điệp），图案取自东湖民间版画；木底座"},"light":{"vi":"Đèn LED ánh sáng vàng ấm, dùng điện cắm trực tiếp","en":"Warm-white LED, plugs directly into mains power","zh":"暖黄色 LED，直接插电使用"},"leadTime":{"vi":"Trung bình 5–7 ngày làm việc","en":"On average 5–7 working days","zh":"平均 5–7 个工作日"}}'::jsonb, '{"vi":"Khi nhắc đến cái tên \"Tam Dương\", nhiều người nghĩ ngay đến ba con dê. Nhưng bức tranh Tam Dương Khai Thái của Đông Hồ lại gây tò mò bởi hai chú gà trống đứng gần như đối xứng nhau, phía sau là những hình ảnh gợi liên tưởng đến mặt trời.\n\nTheo cách lý giải trong tư liệu của nhóm, \"Dương\" ở đây gắn với khái niệm Âm Dương, \"Tam Dương\" được liên hệ với ba hào Dương của quẻ Càn, còn \"Khai Thái\" gắn với quẻ Địa Thiên Thái — giai đoạn thuận lợi khi những yếu tố tưởng như đối lập bắt đầu vận hành hài hòa.\n\nTrong đời sống người Việt, tiếng gà gáy gắn với khoảnh khắc bình minh, lúc một ngày mới bắt đầu. Hai chú gà vì thế có thể được hiểu như sức sống đang thức dậy, của một ngày mới và của những điều tốt đẹp đang mở ra phía trước.\n\nTreo tranh vào dịp Tết như một lời chúc: mong năm mới mở ra nhiều cơ hội, công việc thuận lợi, gia đình bình an và mọi việc có một khởi đầu tốt. Trạng thái tắt đèn cho thấy rõ chất giấy và artwork; khi bật sáng, ánh vàng ấm làm bức tranh thành một phần của không gian.","en":"Hearing the name \"Tam Dương\", many people think of three goats. Yet the Dong Ho painting Tam Dương Khai Thái is intriguing for its two roosters standing almost symmetrically, with sun-like shapes behind them.\n\nAccording to the interpretation in our team''s reference material, \"Dương\" here relates to yin and yang, \"Tam Dương\" to the three yang lines of the Càn hexagram, and \"Khai Thái\" to the hexagram Địa Thiên Thái — a favourable phase in which seemingly opposite forces begin to work in harmony.\n\nIn Vietnamese life the rooster''s crow marks dawn, when a new day begins. The two roosters can therefore be read as vitality waking up, a new day, and good things opening ahead.\n\nHanging the painting at Tết is like making a wish: that the new year opens many opportunities, work goes smoothly, the family stays safe and everything gets a good start. Switched off, the lantern shows the paper and artwork clearly; lit, its warm glow makes the painting part of the room.","zh":"提到“三阳”，许多人先想到三只羊。但东湖版画《三阳开泰》却引人好奇：画中是两只几乎对称站立的雄鸡，身后是令人联想到太阳的图形。\n\n按团队资料中的解读，这里的“阳”与阴阳概念相关，“三阳”对应乾卦的三个阳爻，“开泰”则关联地天泰卦——看似相反的力量开始和谐运转的顺遂阶段。\n\n在越南人的生活里，鸡鸣意味着黎明、新一天的开始。因此两只雄鸡可以被理解为苏醒的生命力、崭新的一天，以及正在前方展开的美好。\n\n春节悬挂此画，如同一句祝愿：愿新的一年机遇不断、工作顺利、家人平安、万事有个好开端。熄灯时可清楚看到纸张与图案；点亮后，暖黄的光让画成为空间的一部分。"}'::jsonb) on conflict (id) do nothing;
insert into public.products (id, slug, kind, status, price, tone, sort_order, name, description, badge, collection_slug, piece_order, specs, story) values ('11111111-1111-4111-8111-0000000000a5', 'den-lon-dan', 'single', 'published', 1400000, 'dusk', 5, '{"vi":"Đèn Lợn Đàn","en":"Pig Herd Lantern (Lon Dan)","zh":"猪群灯（Lợn Đàn）"}'::jsonb, '{"vi":"Đàn lợn quây quần với những vòng xoáy âm dương — mong ước sung túc và hòa hợp","en":"A gathered herd of pigs with yin-yang swirls — a wish for plenty and harmony","zh":"成群的猪与阴阳漩涡——祈愿富足与和睦"}'::jsonb, null, 'bo-suu-tap-dau-tien', 5, '{"size":{"vi":"Thân đèn cao 20 cm, đường kính 12 cm; đế gỗ cao 5 cm, đường kính 12 cm","en":"Lantern body 20 cm tall, 12 cm in diameter; wooden base 5 cm tall, 12 cm in diameter","zh":"灯身高 20 厘米、直径 12 厘米；木底座高 5 厘米、直径 12 厘米"},"material":{"vi":"Giấy dó Dương Ổ – Phong Khê phủ điệp, artwork tranh dân gian Đông Hồ; đế gỗ","en":"Dó paper from Duong O – Phong Khe, coated with điệp, artwork from Dong Ho folk painting; wooden base","zh":"杨坞—风溪手工纸，涂贝壳粉（điệp），图案取自东湖民间版画；木底座"},"light":{"vi":"Đèn LED ánh sáng vàng ấm, dùng điện cắm trực tiếp","en":"Warm-white LED, plugs directly into mains power","zh":"暖黄色 LED，直接插电使用"},"leadTime":{"vi":"Trung bình 5–7 ngày làm việc","en":"On average 5–7 working days","zh":"平均 5–7 个工作日"}}'::jsonb, '{"vi":"Trong những bức tranh Đông Hồ, hình ảnh đàn lợn là một trong những hình tượng gần gũi nhất với đời sống người Việt. Ngày trước, một đàn lợn đông đúc đồng nghĩa với cuộc sống có của ăn của để, nên tranh đàn lợn thường được treo vào dịp Tết, gửi gắm mong muốn về một năm mới đủ đầy và thịnh vượng.\n\nĐiều làm bức tranh đặc biệt nằm ở những vòng xoáy trên thân lợn. Theo cách lý giải trong tư liệu của nhóm, các xoáy ấy gắn với quan niệm Âm Dương: hai mặt đối lập vừa khác nhau, vừa bổ trợ cho nhau, từ đó tạo nên sự sinh sôi và phát triển. Các xoáy trên từng con không hoàn toàn giống nhau — mỗi cá thể vừa mang dấu ấn của nguồn gốc, vừa có nét riêng của chính mình.\n\nTừ hình ảnh đàn lợn, câu chuyện mở rộng sang cách người xưa nhìn về gia đình: muốn yên ấm không chỉ cần vật chất mà còn cần sự hòa hợp giữa các thành viên. Sự đủ đầy không tự nhiên mà có; nó bắt đầu từ sự hòa hợp.\n\nKhi artwork được đưa lên một thân đèn hình trụ, bạn không nhìn toàn bộ trong một khung phẳng: hãy xoay, bước quanh hoặc nhìn từ nhiều phía để khám phá từng chi tiết.","en":"Among Dong Ho paintings, the herd of pigs is one of the images closest to Vietnamese daily life. In the past a large herd meant a life with plenty to eat and keep, so paintings of pig herds were hung at Tết to express hopes for a full and prosperous new year.\n\nWhat makes this painting special are the swirls on the pigs'' bodies. According to the interpretation in our team''s reference material, these swirls relate to yin and yang: two opposites that differ yet complement each other, and so give rise to growth. The swirls on each pig are not quite the same — each one carries the mark of its origins and its own individuality.\n\nFrom the herd, the story widens to how people in the past viewed the family: a warm home needs not only material comfort but harmony among its members. Plenty does not come by itself; it begins with harmony.\n\nWith the artwork wrapped around a cylindrical body, you do not see it all in one flat frame: turn it, walk around it or look from several sides to discover each detail.","zh":"在东湖版画中，猪群是最贴近越南人生活的形象之一。过去，猪群兴旺意味着衣食无忧，因此春节常悬挂猪群画，寄托对新一年富足兴旺的期盼。\n\n这幅画的特别之处在于猪身上的漩涡。按团队资料中的解读，这些漩涡与阴阳观念相关：两个对立面既不同又互补，由此孕育生长与发展。每头猪身上的漩涡并不完全一样——每一个体既带着来源的印记，又有自己的特点。\n\n从猪群出发，故事延伸到古人看待家庭的方式：想要安稳温暖，不仅需要物质，还需要家人之间的和睦。富足并非凭空而来，它始于和睦。\n\n当图案环绕在圆柱形灯身上，你无法在一个平面画框中一览无余：转一转、绕着走，或从不同角度，去发现每一个细节。"}'::jsonb) on conflict (id) do nothing;
insert into public.faq_entries (id, sort_order, is_published, question, answer) values ('22222222-2222-4222-8222-000000000001', 1, true, '{"vi":"Video và lời chúc lưu giữ được bao lâu?","en":"How long are the videos and messages kept?","zh":"视频和祝福会保存多久？"}'::jsonb, '{"vi":"Lời chúc dạng chữ được lưu vĩnh viễn. Lời chúc bằng giọng nói hoặc video được lưu 30 ngày kể từ khi người nhận bấm \"Tôi đã nhận được quà\" — hãy bấm \"Tải về\" để giữ lại. Video hành trình mẻ đèn (mở từ thiệp cảm ơn) được lưu vĩnh viễn.","en":"Text messages are kept forever. Voice and video messages are kept for 30 days after the recipient taps \"I have received my gift\" — tap \"Download\" to keep a copy. The video of how the batch was made (opened from the thank-you card) is kept forever.","zh":"文字祝福永久保存。语音或视频祝福在收礼人点击“我已收到礼物”后保存 30 天——请点击“下载”保留副本。灯的制作视频（通过感谢卡打开）永久保存。"}'::jsonb) on conflict (id) do nothing;
insert into public.faq_entries (id, sort_order, is_published, question, answer) values ('22222222-2222-4222-8222-000000000002', 2, true, '{"vi":"Tôi có thể chỉnh sửa lời chúc sau khi đặt hàng không?","en":"Can I edit my message after ordering?","zh":"下单后可以修改祝福吗？"}'::jsonb, '{"vi":"Có. Bạn chỉnh sửa lời chúc trong trang tài khoản. Phần chữ được khóa khi đơn đã đóng gói (vì thiệp viết tay đã được viết); giọng nói và video sửa được cho đến khi đơn được gửi đi.","en":"Yes. You can edit your message in your account. The text is locked once the order is packed (the handwritten card has been written); voice and video can be changed until the order ships.","zh":"可以。您可以在账户页面修改祝福。订单打包后文字将被锁定（手写卡片已写好）；语音和视频可修改至订单发货前。"}'::jsonb) on conflict (id) do nothing;
insert into public.faq_entries (id, sort_order, is_published, question, answer) values ('22222222-2222-4222-8222-000000000003', 3, true, '{"vi":"Người nhận có cần tải ứng dụng để xem không?","en":"Does the recipient need to install an app?","zh":"收礼人需要安装应用吗？"}'::jsonb, '{"vi":"Không cần. Chỉ cần quét mã bằng camera điện thoại, nội dung mở ngay trên trình duyệt.","en":"No. Just scan the code with the phone camera and the content opens in the browser.","zh":"不需要。只需用手机相机扫码，内容即在浏览器中打开。"}'::jsonb) on conflict (id) do nothing;
insert into public.faq_entries (id, sort_order, is_published, question, answer) values ('22222222-2222-4222-8222-000000000004', 4, true, '{"vi":"Đèn giấy dó có dễ vỡ khi vận chuyển không?","en":"Are dó paper lanterns fragile in shipping?","zh":"纸灯在运输中容易损坏吗？"}'::jsonb, '{"vi":"Thân đèn giấy dó được giữ form bằng lớp lót bên trong và đặt trên đế gỗ; mỗi đèn được đóng gói trong hộp có lớp đệm chuyên dụng cho hàng thủ công dễ vỡ.","en":"The dó paper body is held in shape by an inner liner and set on a wooden base; each lantern is packed in a padded box made for fragile handicrafts.","zh":"纸灯身由内衬定型，立于木底座上；每盏灯都装入专为易碎手工艺品设计的缓冲盒中。"}'::jsonb) on conflict (id) do nothing;
insert into public.faq_entries (id, sort_order, is_published, question, answer) values ('22222222-2222-4222-8222-000000000005', 5, true, '{"vi":"Thời gian hoàn thành một chiếc đèn đặt riêng là bao lâu?","en":"How long does it take to make a lantern?","zh":"制作一盏灯需要多长时间？"}'::jsonb, '{"vi":"Trung bình 5–7 ngày làm việc, tuỳ theo mẫu và khối lượng đơn tại xưởng vào thời điểm đặt hàng.","en":"On average 5–7 working days, depending on the model and the workshop’s workload at the time of ordering.","zh":"平均 5–7 个工作日，视款式及下单时工坊的订单量而定。"}'::jsonb) on conflict (id) do nothing;
insert into public.faq_entries (id, sort_order, is_published, question, answer) values ('22222222-2222-4222-8222-000000000006', 6, true, '{"vi":"Giấy dó và giấy điệp có phải là một không?","en":"Are dó paper and điệp paper the same thing?","zh":"桑皮纸（dó）和贝粉纸（điệp）是同一种纸吗？"}'::jsonb, '{"vi":"Không hoàn toàn. Giấy dó là nền giấy thủ công; giấy điệp là giấy dó sau khi được phủ thêm lớp điệp trên bề mặt. Tranh Đông Hồ là một hệ thống rộng hơn, gắn với nền giấy, lớp điệp, màu sắc, bản khắc, kỹ thuật thực hiện và đề tài dân gian.","en":"Not quite. Dó paper is the handmade base paper; điệp paper is dó paper with an extra điệp coating on its surface. Dong Ho painting is a wider system tied to the paper, the coating, colours, woodblocks, technique and folk subjects.","zh":"不完全是。dó 纸是手工纸基底；điệp 纸是在 dó 纸表面再涂一层贝壳粉（điệp）。东湖版画则是更大的体系，涵盖纸、涂层、颜色、雕版、技法与民间题材。"}'::jsonb) on conflict (id) do nothing;
insert into public.faq_entries (id, sort_order, is_published, question, answer) values ('22222222-2222-4222-8222-000000000007', 7, true, '{"vi":"Giấy và tranh trên đèn đến từ đâu?","en":"Where do the paper and artwork on the lanterns come from?","zh":"灯上的纸和图案从哪里来？"}'::jsonb, '{"vi":"Giấy dó được lấy trực tiếp từ cơ sở làm giấy tại Dương Ổ – Phong Khê, rồi đưa tới Đông Hồ để phủ điệp và thực hiện phần nghệ thuật. LAMVI hoàn thiện cấu trúc đèn, ánh sáng, đóng gói và trải nghiệm kể chuyện số.","en":"The dó paper comes straight from a papermaking workshop in Duong O – Phong Khe, then goes to Dong Ho for the điệp coating and the artwork. LAMVI finishes the lantern structure, lighting, packaging and the digital storytelling.","zh":"dó 纸直接取自杨坞—风溪的造纸作坊，再送到东湖涂贝壳粉并完成图案；LAMVI 负责灯的结构、光源、包装与数字叙事体验。"}'::jsonb) on conflict (id) do nothing;
insert into public.faq_entries (id, sort_order, is_published, question, answer) values ('22222222-2222-4222-8222-000000000008', 8, true, '{"vi":"Mã QR nằm ở đâu trên sản phẩm?","en":"Where is the QR code on the product?","zh":"二维码在产品的什么位置？"}'::jsonb, '{"vi":"LAMVI không đặt QR hay khắc lời nhắn lên đèn hoặc đế gỗ. Mã QR nằm trên thiệp cảm ơn đi kèm; quét mã sẽ mở lời chúc của người tặng và video hành trình mẻ đèn.","en":"LAMVI does not place a QR code or engrave a message on the lantern or its wooden base. The QR code is on the accompanying thank-you card; scanning it opens the giver’s message and the video of how the batch was made.","zh":"LAMVI 不会在灯身或木底座上放置二维码或刻字。二维码位于随附的感谢卡上；扫码即可打开送礼人的祝福和灯的制作视频。"}'::jsonb) on conflict (id) do nothing;
insert into public.faq_entries (id, sort_order, is_published, question, answer) values ('22222222-2222-4222-8222-000000000009', 9, true, '{"vi":"Đèn có kích thước và nguồn sáng như thế nào?","en":"What are the size and light source of the lantern?","zh":"灯的尺寸和光源是怎样的？"}'::jsonb, '{"vi":"Thân đèn cao 20 cm, đường kính 12 cm, đặt trên đế gỗ cao 5 cm. Đèn dùng LED ánh sáng vàng ấm và cắm điện trực tiếp.","en":"The lantern body is 20 cm tall and 12 cm in diameter, on a 5 cm wooden base. It uses a warm-white LED and plugs directly into mains power.","zh":"灯身高 20 厘米、直径 12 厘米，立于高 5 厘米的木底座上；使用暖黄色 LED，直接插电。"}'::jsonb) on conflict (id) do nothing;
